--
-- Table structure for table `video_games_sales`
--

DROP TABLE IF EXISTS `video_games_sales`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `video_games_sales` (
  `video_games_rank` int NOT NULL AUTO_INCREMENT,
  `release_year` int NOT NULL,
  `NA_Sales` float DEFAULT NULL,
  `EU_Sales` float DEFAULT NULL,
  `JP_Sales` float DEFAULT NULL,
  `Global_Sales` float DEFAULT NULL,
  `Other_Sales` float DEFAULT NULL,
  `platform_id` int DEFAULT NULL,
  `title_id` int DEFAULT NULL,
  `genre_id` int DEFAULT NULL,
  `publisher_id` int DEFAULT NULL,
  PRIMARY KEY (`video_games_rank`),
  KEY `platform_id` (`platform_id`),
  KEY `publisher_id` (`publisher_id`),
  KEY `title_id` (`title_id`),
  KEY `genre_id` (`genre_id`),
  CONSTRAINT `genre_id` FOREIGN KEY (`genre_id`) REFERENCES `genre` (`genre_id`),
  CONSTRAINT `platform_id` FOREIGN KEY (`platform_id`) REFERENCES `platform` (`platform_id`),
  CONSTRAINT `publisher_id` FOREIGN KEY (`publisher_id`) REFERENCES `publisher` (`publisher_id`),
  CONSTRAINT `title_id` FOREIGN KEY (`title_id`) REFERENCES `title` (`title_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1000 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

